normalmente. Porque? E debugando observo que "n" é um vetor de 15
posições. Como "n" adquire esse valor?

dsad <- Vectorize(FUN=
                  function(y,a,lambda){
                    poi <- function(y,n){
                      w <- y*log(a*n)-lfactorial(y)-a*n
                      exp(w)
                    }
                    f1 <- function(n){
                      dexp(n,rate=lambda) * poi(y,n)
                    }
                    integrate(f1,0,Inf)$value
                  },
                  "y")
